using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class BowlingChecks {
 public static string LastReport{get;private set;}
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  Require(JsonUtility.FromJson<WorldPlayMemory>("{}").Valid(),"Legacy play save rejected");var m=new BowlingMemory();m.Complete(false,6,false);Require(m.observedRolls==0&&m.bestPlayer==6,"Unwitnessed demonstration learned");m.Complete(false,2,true);m.Complete(true,3,false);Require(m.observedRolls==1&&m.playerPins==8&&m.creaturePins==3&&m.practice>0,"Typed bowling results incorrect");var saved=JsonUtility.FromJson<BowlingMemory>(JsonUtility.ToJson(m));Require(saved.Valid(),"Bowling save rejected");saved.observedRolls=3;Require(!saved.Valid(),"Invented observations accepted");saved.observedRolls=1;saved.practice=float.NaN;Require(!saved.Valid(),"Invalid practice accepted");var h=new HybridState();h.receipt.bowling=true;Require(!h.Valid(),"Bowling attributed to another action");h.receipt.action=CreatureAction.PlayWithToy;Require(h.Valid(),"Typed bowling receipt rejected");h.receipt.fetched=true;Require(!h.Valid(),"Fetch and bowling receipt conflated");Debug.Log("BWVR_BOWLING_MODEL_PASS: old saves, witnessed learning, score/practice bounds, persistence and typed feedback");
 }
 [MenuItem("BWVR/Verify giant bowling and imitation (Play mode)")]
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var ball=slice.GetComponentInChildren<BeachBall>();var lane=ball.Bowling;Require(lane?.Available==true,"No playable bowling lane");var nav=god.GetComponent<IslandNavigator>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=(SliceState)field.GetValue(slice);var people=slice.GetComponentsInChildren<VillagerSocial>();var godAt=god.transform.position;var godRotation=god.transform.rotation;var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var held=(CarryItem[])typeof(QuestSlice).GetField("held",flags).GetValue(slice);Require(held.All(i=>i==null),"Release held objects first");
  void Cancel(){god.Interrupt("Bowling QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();}}
  var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f,playPreference=.8f};
  void StageObserver(bool visible){Require(nav.world.Sample(lane.Start-lane.Right*(visible?12:100)*nav.world.Scale,nav.profile,8,out var at),"No observer position");god.transform.position=nav.world.ProjectFoot(at,nav.profile);god.transform.LookAt(lane.Target);nav.ResetRoute();Physics.SyncTransforms();}
  void PlayerRoll(){var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);var item=ball.GetComponent<CarryItem>();Require((bool)typeof(QuestSlice).GetMethod("TryGrab",flags).Invoke(slice,new object[]{1,item}),"Native ball pickup failed");var motion=(ThrowMotion[])typeof(QuestSlice).GetField("throwMotion",flags).GetValue(slice);var rig=(Transform)typeof(QuestSlice).GetField("rig",flags).GetValue(slice);for(int i=0;i<4;i++)motion[1].Sample(lane.Start+lane.Forward*i*.02f*rig.localScale.x,i*.02f,rig.localScale.x);typeof(QuestSlice).GetMethod("Release",flags).Invoke(slice,new object[]{1,new Ray(lane.Start,lane.Forward)});Require(lane.Active&&!ball.FetchReserved&&held[1]==null,"Native player roll did not enter bowling / retained fetch");}
  void AdvancePlayer(){for(int i=0;i<300&&lane.Active;i++){test.Hybrid.time+=.05f;ball.Advance(.05f,false);}}
  try{
   var reset=GameObject.Find("Reset bowling rack");Require(reset!=null,"Reset control missing");Physics.SyncTransforms();Require(Physics.Raycast(new Ray(reset.transform.position-lane.Forward*nav.world.Scale*10,lane.Forward),out var resetHit,nav.world.Scale*12)&&resetHit.collider.GetComponent<SpatialTarget>()!=null,"World pointer cannot reach reset control");
   Cancel();field.SetValue(slice,test);god.NewSeason();ball.ResetWorld();StageObserver(true);Require(!lane.CanImitate(god.transform.position),"Creature knew bowling without a demonstration");PlayerRoll();Require(!lane.TryReset()&&!ball.GetComponent<CreatureAffordance>().Available,"Active roll reset or was stealable");var before=ball.Body.position;var pins=lane.Pins.Select(p=>p.position).ToArray();test.paused=true;ball.Advance(1,true);Require(ball.Body.position==before&&lane.Pins.Select(p=>p.position).SequenceEqual(pins)&&test.WorldPlay.Bowling.playerRolls==0,"Pause moved/scored the roll");test.paused=false;AdvancePlayer();
   Require(!lane.Active&&lane.LastScore>0&&lane.FallenMask!=0&&test.WorldPlay.Bowling.playerRolls==1&&test.WorldPlay.Bowling.observedRolls==1,"Physical pins did not fall or witnessed roll was not learned");int playerPins=test.WorldPlay.Bowling.playerPins;ball.Advance(.05f,false);Require(test.WorldPlay.Bowling.playerRolls==1&&test.WorldPlay.Bowling.playerPins==playerPins,"Result credited twice");resetHit.collider.GetComponent<SpatialTarget>().Activate();Require(lane.FallenMask==0,"Physical pointer reset failed");StageObserver(true);Require(lane.CanImitate(god.transform.position),"Witnessed game did not become a feasible opportunity");
   bool selected=false;for(int i=0;i<1800&&!test.Hybrid.receipt.bowling;i++){god.Tick(.05f);ball.Advance(.05f,false);selected|=god.State.intention.active&&god.State.intention.target==ball.StableId;}
   Require(selected&&test.WorldPlay.Bowling.creatureRolls==1&&test.Hybrid.receipt.bowling,"Creature did not select/perform bowling through normal utility: "+god.Explanation);
   float preference=test.WorldPlay.Bowling.preference;Require(god.Feedback(true)&&!god.Feedback(true)&&test.WorldPlay.Bowling.preference>preference,"Completed bowling lesson missing or repeatable");var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.WorldPlay.Bowling.observedRolls==1&&saved.WorldPlay.Bowling.creatureRolls==1,"Bowling memory failed save round trip");
   LastReport="BWVR_BOWLING_PLAY_PASS: native measured toss -> "+playerPins+" real fallen pins -> witnessed discovery -> utility-selected creature roll ("+test.WorldPlay.Bowling.creaturePins+" pins) -> one-shot contextual feedback; pause, exclusion, physical reset and save passed";Debug.Log(LastReport);
   Cancel();test=new SliceState{developmentFocus=true,water=100,crops=100};field.SetValue(slice,test);god.NewSeason();ball.ResetWorld();StageObserver(false);PlayerRoll();AdvancePlayer();Require(test.WorldPlay.Bowling.playerRolls==1&&test.WorldPlay.Bowling.observedRolls==0&&!lane.CanImitate(god.transform.position),"Distant unwitnessed shot taught bowling");
   Require(lane.TryReset(),"Cancellation reset failed");PlayerRoll();int completed=test.WorldPlay.Bowling.playerRolls;ball.GetComponent<CarryItem>().held=true;ball.Advance(.05f,false);ball.GetComponent<CarryItem>().held=false;ball.PlaceOnGround(lane.Start);Require(!lane.Active&&test.WorldPlay.Bowling.playerRolls==completed,"Picked-up/canceled shot gained completion");
   Debug.Log("BWVR_BOWLING_UNWITNESSED_PASS: physical result retained; absent creature learned nothing");
  }finally{if(held[1]!=null){held[1].held=false;held[1].GetComponent<Collider>().enabled=true;held[1]=null;}Cancel();field.SetValue(slice,original);god.NewSeason();ball.ResetWorld();god.transform.SetPositionAndRotation(godAt,godRotation);nav.ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
